import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.il0noOp3.js";const p=JSON.parse('{"title":"Azure Scout — overview and required access","description":"Executive overview of Azure Scout and the exact least-privilege access it needs — Azure RBAC, Microsoft Entra, Microsoft Graph and Azure DevOps.","frontmatter":{"description":"Executive overview of Azure Scout and the exact least-privilege access it needs — Azure RBAC, Microsoft Entra, Microsoft Graph and Azure DevOps."},"headers":[],"relativePath":"guide/azure-scout-overview-and-access.md","filePath":"guide/azure-scout-overview-and-access.md"}'),n={name:"guide/azure-scout-overview-and-access.md"};function s(i,e,d,c,l,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="azure-scout-—-overview-and-required-access" tabindex="-1">Azure Scout — overview and required access <a class="header-anchor" href="#azure-scout-—-overview-and-required-access" aria-label="Permalink to &quot;Azure Scout — overview and required access&quot;">​</a></h1><p><strong>Audience:</strong> the sponsor approving the engagement, and the platform or security team granting the access. Sections 1–2 are the executive summary; sections 3 onward are the access request.</p><hr><h2 id="_1-what-azure-scout-is" tabindex="-1">1. What Azure Scout is <a class="header-anchor" href="#_1-what-azure-scout-is" aria-label="Permalink to &quot;1. What Azure Scout is&quot;">​</a></h2><p>Azure Scout inventories an Azure estate and assesses it against Microsoft&#39;s own published frameworks, then produces the deliverable an assessment engagement is normally written by hand: a single self-contained report page carrying the inventory, every assessment, the evidence behind each finding, and the prioritised path back to compliance — which you can export to PDF, Word, Markdown or CSV.</p><blockquote><p>Standalone Word, PowerPoint, PDF, Excel and Power BI outputs are <strong>coming soon</strong>: they are being rebuilt to generate from that report rather than alongside it, so a document and the page it came from can never disagree (<strong>AB#6922</strong>).</p></blockquote><p>It is <strong>read-only</strong>. Scout never creates, modifies or deletes anything in the tenant, and it holds no standing access — it runs under credentials you grant, for as long as you choose to grant them.</p><h3 id="what-it-answers" tabindex="-1">What it answers <a class="header-anchor" href="#what-it-answers" aria-label="Permalink to &quot;What it answers&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Question</th><th>How</th></tr></thead><tbody><tr><td>What is actually deployed?</td><td>Full resource inventory across every Azure service category, plus Microsoft Entra objects</td></tr><tr><td>How does it measure against Microsoft&#39;s guidance?</td><td>Scored against the <strong>Cloud Adoption Framework</strong> landing-zone design areas and the <strong>Well-Architected Framework</strong> pillars</td></tr><tr><td>Where is the regulatory exposure?</td><td>Microsoft Cloud Security Benchmark, plus every regulatory initiative already assigned in the scope</td></tr><tr><td>What should be fixed first?</td><td>Findings ranked by severity, each carrying its supporting number and the affected resource IDs</td></tr><tr><td>What was <em>not</em> checked?</td><td>Stated explicitly — see below</td></tr></tbody></table><h3 id="what-makes-the-output-usable" tabindex="-1">What makes the output usable <a class="header-anchor" href="#what-makes-the-output-usable" aria-label="Permalink to &quot;What makes the output usable&quot;">​</a></h3><ul><li><strong>Every finding carries its supporting number and the affected resources.</strong> &quot;60 of 198 storage accounts&quot;, never &quot;storage accounts are misconfigured&quot;. A finding that cannot be actioned is decoration.</li><li><strong>&quot;Not assessed&quot; is a first-class result.</strong> A control with no automated rule, or one whose data source was unavailable, is reported as <em>not assessed</em> — never as a pass and never as a zero. It is excluded from the compliance denominator rather than quietly counted as a failure.</li><li><strong>The deck states what was out of scope</strong>, and carries exactly one &quot;act on this first&quot; slide naming a specific item.</li><li><strong>A triage column on every evidence row</strong> — real / by-design / sandbox / legacy — seeded for your reviewer rather than guessed. This is what turns a raw finding list into a decision.</li></ul><h3 id="what-it-is-not" tabindex="-1">What it is not <a class="header-anchor" href="#what-it-is-not" aria-label="Permalink to &quot;What it is not&quot;">​</a></h3><p>Scout does not read data. It reads the <strong>control plane</strong>: resource configuration, policy state and directory metadata. It does not read blob contents, database rows, Key Vault secret <em>values</em>, mail or documents. Key Vault items are read as names and expiry dates only.</p><hr><h2 id="_2-how-an-engagement-runs" tabindex="-1">2. How an engagement runs <a class="header-anchor" href="#_2-how-an-engagement-runs" aria-label="Permalink to &quot;2. How an engagement runs&quot;">​</a></h2><ol><li>Access is granted (section 3), typically for the duration of the assessment.</li><li>Scout runs from a workstation or a pipeline. A mid-size estate takes 10–30 minutes.</li><li>The collected data can be banked once and every report regenerated from it offline — so revisions cost seconds and require no further tenant access.</li><li>Deliverables are produced per assessment, plus a cross-assessment executive roll-up.</li></ol><p>Access can be revoked the moment collection finishes; report generation needs none.</p><hr><h2 id="_3-azure-rbac-—-the-control-plane" tabindex="-1">3. Azure RBAC — the control plane <a class="header-anchor" href="#_3-azure-rbac-—-the-control-plane" aria-label="Permalink to &quot;3. Azure RBAC — the control plane&quot;">​</a></h2><h3 id="the-recommended-grant" tabindex="-1">The recommended grant <a class="header-anchor" href="#the-recommended-grant" aria-label="Permalink to &quot;The recommended grant&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Role</th><th>Scope</th><th>Why</th></tr></thead><tbody><tr><td><strong>Reader</strong></td><td><strong>Root management group</strong> (Tenant Root Group)</td><td>One assignment, inherited by every management group, subscription and resource group beneath it</td></tr></tbody></table><p>This is the <strong>entire Azure RBAC requirement</strong>. Reader is a built-in role that confers no write, no delete and no data-plane access.</p><p>Assigning at the root management group is preferred over per-subscription assignment for two reasons: it is one auditable grant instead of many, and it means a subscription created mid- engagement is covered without a second request.</p><blockquote><p><strong>Verified, not assumed:</strong> Reader at the root management group is sufficient on its own. A separate <em>Management Group Reader</em> role is <strong>not</strong> required — the Reader role already carries the management-group read actions Scout uses.</p></blockquote><h3 id="if-root-level-assignment-is-not-permitted" tabindex="-1">If root-level assignment is not permitted <a class="header-anchor" href="#if-root-level-assignment-is-not-permitted" aria-label="Permalink to &quot;If root-level assignment is not permitted&quot;">​</a></h3><p>Reader on each in-scope subscription works. The trade-off is explicit and should be recorded: management-group hierarchy and any policy assigned above subscription level become invisible, so governance findings will be reported as <strong>not assessed</strong> rather than silently passing.</p><h3 id="optional-additions" tabindex="-1">Optional additions <a class="header-anchor" href="#optional-additions" aria-label="Permalink to &quot;Optional additions&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Role</th><th>Scope</th><th>Needed only for</th></tr></thead><tbody><tr><td><strong>Cost Management Reader</strong></td><td>Billing scope or subscription</td><td>Cost analysis (<code>-IncludeCosts</code>). Reader alone cannot query the cost APIs</td></tr></tbody></table><p>Nothing else. If a capability is unavailable, Scout reports it as not assessed and names the missing permission — it does not fail the run and does not report a gap it could not measure.</p><hr><h2 id="_4-microsoft-entra-id-—-directory-read-access" tabindex="-1">4. Microsoft Entra ID — directory read access <a class="header-anchor" href="#_4-microsoft-entra-id-—-directory-read-access" aria-label="Permalink to &quot;4. Microsoft Entra ID — directory read access&quot;">​</a></h2><p>Directory objects are read through <strong>Microsoft Graph</strong>. Two options:</p><h3 id="option-a-—-a-delegated-user-interactive-runs" tabindex="-1">Option A — a delegated user (interactive runs) <a class="header-anchor" href="#option-a-—-a-delegated-user-interactive-runs" aria-label="Permalink to &quot;Option A — a delegated user (interactive runs)&quot;">​</a></h3><p>Assign the built-in Entra role <strong>Global Reader</strong>. It is read-only across the directory and covers every Graph call below in one grant.</p><h3 id="option-b-—-a-service-principal-automation-and-the-recommended-route" tabindex="-1">Option B — a service principal (automation, and the recommended route) <a class="header-anchor" href="#option-b-—-a-service-principal-automation-and-the-recommended-route" aria-label="Permalink to &quot;Option B — a service principal (automation, and the recommended route)&quot;">​</a></h3><p>Grant <strong>application permissions</strong> on Microsoft Graph, each requiring admin consent. All are <code>.Read</code>; none permits a write.</p><table tabindex="0"><thead><tr><th>Graph application permission</th><th>What Scout reads with it</th></tr></thead><tbody><tr><td><code>Directory.Read.All</code></td><td>Baseline directory read</td></tr><tr><td><code>User.Read.All</code></td><td>User accounts and their state</td></tr><tr><td><code>Group.Read.All</code></td><td>Groups and membership</td></tr><tr><td><code>Application.Read.All</code></td><td>App registrations, service principals, credential expiry</td></tr><tr><td><code>Policy.Read.All</code></td><td>Conditional Access, authorisation and authentication method policies</td></tr><tr><td><code>RoleManagement.Read.Directory</code></td><td>Directory role assignments</td></tr><tr><td><code>Organization.Read.All</code></td><td>Tenant profile and licensing posture</td></tr><tr><td><code>Domain.Read.All</code></td><td>Verified domains and federation configuration</td></tr><tr><td><code>AdministrativeUnit.Read.All</code></td><td>Administrative units</td></tr><tr><td><code>IdentityRiskyUser.Read.All</code></td><td>Identity Protection risky users — <strong>requires Entra ID P2</strong></td></tr><tr><td><code>PrivilegedAccess.Read.AzureResources</code></td><td>PIM eligibility and activation</td></tr></tbody></table><p>If a permission is withheld, the findings that depend on it are reported as <strong>not assessed</strong> and name the permission — the run continues and the rest of the report is unaffected.</p><h3 id="do-not-grant" tabindex="-1">Do not grant <a class="header-anchor" href="#do-not-grant" aria-label="Permalink to &quot;Do not grant&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Permission</th><th>Why not</th></tr></thead><tbody><tr><td><code>IdentityProvider.Read.All</code></td><td>Scout queries external identity providers but <strong>no collector reads the result</strong>. Granting it widens your consent surface for no coverage. Scout&#39;s own permission audit warns about this by design — a permission the tool asks for and does not need belongs in the report, not in a code comment.</td></tr></tbody></table><p>Scout&#39;s permission audit distinguishes the two cases deliberately, and the wording is worth knowing before you read its output:</p><ul><li><strong><code>[WARN] … queried but NO collector reads the result. Do not grant it.</code></strong> — working as intended. Leave the permission ungranted; nothing in the report depends on it.</li><li><strong><code>[FAIL] … DENIED — N collectors will be empty</code></strong> — a real gap. Granting it fills those collectors; leaving it means those findings are reported as <em>not assessed</em>.</li></ul><hr><h2 id="_4a-what-licence-tier-affects-—-and-what-it-does-not" tabindex="-1">4a. What licence tier affects — and what it does not <a class="header-anchor" href="#_4a-what-licence-tier-affects-—-and-what-it-does-not" aria-label="Permalink to &quot;4a. What licence tier affects — and what it does not&quot;">​</a></h2><p><strong>Scout runs, and produces its full report, on a tenant with no premium Entra licence at all.</strong> Licensing changes how much of the <em>identity</em> picture can be filled in; it changes nothing about the Azure resource inventory or the CAF/WAF assessment, which are control-plane reads.</p><p>Scout detects the tenant&#39;s licence itself (from <code>subscribedSkus</code>) and reports a licence-gated feature as <strong>not licensed — reported as Not assessed</strong>, not as a permission failure. You will not be told to grant a permission that cannot help.</p><table tabindex="0"><thead><tr><th>Feature</th><th>Needs</th><th>Without it</th></tr></thead><tbody><tr><td>Resource inventory, CAF/WAF assessment, policy and compliance state, Defender findings</td><td><strong>Nothing</strong> — Azure RBAC only</td><td>Full coverage</td></tr><tr><td>Users, groups, apps, service principals, directory roles, domains, administrative units</td><td><strong>Entra ID Free</strong></td><td>Full coverage</td></tr><tr><td>Conditional Access policies, named locations, cross-tenant access</td><td><strong>Entra ID P1</strong></td><td>Reported as <em>Not assessed</em>. Conditional Access does not exist to read on a Free tenant</td></tr><tr><td><strong>Risky users / Identity Protection</strong> (<code>IdentityRiskyUser.Read.All</code>)</td><td><strong>Entra ID P2</strong></td><td><code>Identity/RiskyUsers</code> reported as <em>Not assessed</em>. <strong>Granting the permission does not help</strong> — the endpoint returns nothing without P2</td></tr><tr><td>PIM eligibility and activation (<code>PrivilegedAccess.Read.AzureResources</code>)</td><td><strong>Entra ID P2</strong></td><td>Reported as <em>Not assessed</em>; standing role assignments are still read</td></tr></tbody></table><h3 id="reading-the-permission-audit" tabindex="-1">Reading the permission audit <a class="header-anchor" href="#reading-the-permission-audit" aria-label="Permalink to &quot;Reading the permission audit&quot;">​</a></h3><p>Three verdicts, and they mean different things:</p><table tabindex="0"><thead><tr><th>Verdict</th><th>Meaning</th><th>Action</th></tr></thead><tbody><tr><td><code>[FAIL] … DENIED — N collectors will be empty</code></td><td>A real gap. The permission is missing and granting it fixes the coverage</td><td>Grant it</td></tr><tr><td><code>[WARN] … NOT LICENSED — requires &lt;product&gt;</code></td><td>A licence boundary, not a misconfiguration</td><td><strong>None</strong>, unless you intend to buy that tier. Granting the permission will not populate it</td></tr><tr><td><code>[WARN] … queried but NO collector reads the result. Do not grant it.</code></td><td>Scout asks for something nothing consumes</td><td><strong>Do not grant it</strong></td></tr></tbody></table><p>In every case the affected findings are reported as <strong>Not assessed</strong> and named in the report — never as a pass, never as a zero, and never silently omitted. A gap you chose not to fund still appears as a gap.</p><h3 id="security-data" tabindex="-1">Security data <a class="header-anchor" href="#security-data" aria-label="Permalink to &quot;Security data&quot;">​</a></h3><p>Microsoft Defender for Cloud secure score, recommendations and alerts come through the <strong>Azure control plane</strong> and are covered by the Reader assignment in section 3. <strong>No separate Defender or Sentinel role is required.</strong> If Defender for Cloud is not enabled in scope, those findings are reported as not assessed.</p><hr><h2 id="_5-azure-devops-—-only-if-in-scope" tabindex="-1">5. Azure DevOps — only if in scope <a class="header-anchor" href="#_5-azure-devops-—-only-if-in-scope" aria-label="Permalink to &quot;5. Azure DevOps — only if in scope&quot;">​</a></h2><p>Azure DevOps is <strong>off by default</strong>. It is collected only when explicitly requested (<code>-IncludeDevOps</code>), and Scout reads organisation and project configuration — never source code and never build artefacts.</p><p>Authenticate with either the signed-in identity or a <strong>Personal Access Token</strong>. The PAT needs <strong>read-only</strong> scopes:</p><table tabindex="0"><thead><tr><th>Scope</th><th>Reads</th></tr></thead><tbody><tr><td>Project and Team (Read)</td><td>Organisations and projects</td></tr><tr><td>Build (Read)</td><td>Pipeline definitions</td></tr><tr><td>Code (Read)</td><td>Repository <em>metadata</em> — names, branch policies. <strong>Not file contents</strong></td></tr><tr><td>Service Connections (Read)</td><td>Service endpoints and their authentication <em>type</em></td></tr><tr><td>Agent Pools (Read)</td><td>Agent pool configuration</td></tr></tbody></table><p>A PAT should be issued for the engagement window and revoked afterwards. If DevOps access is declined, the DevOps capability findings are reported as not assessed and nothing else changes.</p><hr><h2 id="_6-summary-—-the-whole-access-request" tabindex="-1">6. Summary — the whole access request <a class="header-anchor" href="#_6-summary-—-the-whole-access-request" aria-label="Permalink to &quot;6. Summary — the whole access request&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Plane</th><th>Grant</th><th>Scope</th></tr></thead><tbody><tr><td><strong>Azure</strong></td><td><code>Reader</code></td><td>Root management group</td></tr><tr><td><strong>Azure</strong> <em>(optional)</em></td><td><code>Cost Management Reader</code></td><td>Billing scope — only for cost analysis</td></tr><tr><td><strong>Entra ID</strong></td><td><code>Global Reader</code>, <strong>or</strong> the Graph application permissions in section 4</td><td>Tenant</td></tr><tr><td><strong>Azure DevOps</strong> <em>(optional)</em></td><td>Read-only PAT</td><td>Organisation</td></tr></tbody></table><p>Every grant above is <strong>read-only</strong>. There is no write permission, no data-plane permission and no standing access anywhere in this list.</p><hr><h2 id="_7-questions-your-security-team-will-ask" tabindex="-1">7. Questions your security team will ask <a class="header-anchor" href="#_7-questions-your-security-team-will-ask" aria-label="Permalink to &quot;7. Questions your security team will ask&quot;">​</a></h2><p><strong>Does it exfiltrate anything?</strong> No. Scout runs where you run it and writes its output to the local path you specify. There is no telemetry, no phone-home and no cloud service component.</p><p><strong>Does it read our data?</strong> No — control plane only. Not blob contents, database rows, Key Vault secret values, mail or documents. Key Vault items are read as names and expiry dates.</p><p><strong>Can it change anything?</strong> No. Every permission listed is read-only, and Scout has no write code path.</p><p><strong>What if we grant less than the above?</strong> The run still completes. Whatever could not be evaluated is reported as <strong>not assessed</strong> and names the missing permission, so the gap is visible in the report rather than hidden as a pass.</p><p><strong>How long do you need the access?</strong> Only for the collection run. The collected data can be banked once and all reporting done offline afterwards, so access can be revoked as soon as collection finishes.</p><p><strong>Do we need Entra ID P1 or P2?</strong> No. Scout runs and reports on a tenant with no premium licence. P1 and P2 add identity coverage — Conditional Access and Identity Protection respectively — and without them those specific findings are reported as <em>Not assessed</em> rather than failing the run. See section 4a.</p><p><strong>Advisor recommendations are missing for one subscription.</strong> Azure Advisor needs the <code>Microsoft.Advisor</code> resource provider registered on each subscription, and it produces nothing until it has assessed one. Scout skips that subscription, names it, and carries on — the other subscriptions are unaffected. To include it: <code>Register-AzResourceProvider -ProviderNamespace Microsoft.Advisor</code>. To omit Advisor entirely, run with <code>-SkipAdvisory</code>.</p>',72)])])}const g=t(n,[["render",s]]);export{p as __pageData,g as default};
